use xiom.io;

fn main() -> Int {
  let original = Vec[Int].new();
  original.push(10);
  original.push(20);
  original.push(30);

  var v1 = original.clone();
  var v2 = original.clone();

  v1.push(40);
  v2.push(50);

  io.println(original.len().to_str());
  io.println(v1.len().to_str());
  io.println(v2.len().to_str());
  return original.len() as Int;
}
